package com.mahweb.mahyarnfc.omnishare.transport; import java.security.PublicKey; import com.mahweb.mahyarnfc.omnishare.crypto.CryptoBox; public final class DeliveryAckValidator { private DeliveryAckValidator(){} public static boolean valid(DeliveryAck a,String tx,String recipient,PublicKey key){return a!=null&&a.transferId.equals(tx)&&a.recipientDeviceId.equals(recipient)&&a.signature.length>0&&CryptoBox.verifyQuiet(key,a.unsignedBytes(),a.signature);} }
